const { TEMPLATES, TYPES, escape: esc, cardMarkup } = require('../public/card-model');
const {categories,examples}=require('../public/examples');
const ideaGuides = require('./idea-guides');
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const assetVersion = crypto.createHash('sha256').update(['styles.css', 'card-model.js', 'examples.js', 'studio.js'].map(file => fs.readFileSync(path.join(__dirname, '../public', file))).join('')).digest('hex').slice(0, 12);

const ORIGIN = 'https://diypokecard.com';
const pricing = require('./pricing.json');
