  photo: '<rect x="3" y="4" width="18" height="16" rx="3"/><circle cx="8" cy="9" r="1.5"/><path d="m3 16 5-5 4 4 4-5 5 6"/>',
  cards: '<rect x="7" y="4" width="13" height="17" rx="2"/><path d="m4 17-2-13a2 2 0 0 1 2-2h10"/><path d="m13.5 8 1 3 3 1-3 1-1 3-1-3-3-1 3-1 1-3Z"/>',
