  dice: '<rect x="3" y="3" width="18" height="18" rx="4"/><circle cx="8" cy="8" r=".6" fill="currentColor"/><circle cx="16" cy="8" r=".6" fill="currentColor"/><circle cx="8" cy="16" r=".6" fill="currentColor"/><circle cx="16" cy="16" r=".6" fill="currentColor"/><circle cx="12" cy="12" r=".6" fill="currentColor"/>',
