function legal(kind, {origin = ORIGIN} = {}) {
  const privacy = kind === 'privacy';
  const title = privacy ? 'Privacy & Your Photos' : 'Terms of Use';
  const content = privacy ? `<h2>The free editor works in your browser</h2><p>Photos added in My photo are decoded and resized locally. They are not uploaded to our server by the regular editor. Drafts and saved collections are stored using your browser’s local storage mechanisms, including IndexedDB. Anyone with access to the same browser profile may be able to see those cards.</p><h2>You control your collection</h2><p>“Keep it” adds a card to this device’s collection. Delete removes it from the collection; a short undo action is available after deletion. Downloaded backups, images, PDFs, and interactive files are separate copies that you control. Clearing site data deletes the local collection and draft. There is no automatic cloud backup.</p><h2>Optional AI processing</h2><p>Choosing Generate original artwork sends your idea or selected creature options to Cloudflare Workers AI. Choosing AI photo transformation sends the photo and card details through our server to Cloudflare Workers AI. An adult must explicitly confirm permission for photo transformation, including parental permission for a child’s image. We do not intentionally save source photo uploads on our server after processing; generated artwork, the submitted idea, and card details are stored privately in Cloudflare R2 and D1 to support credit accounting and optional email delivery. Provider retention follows that provider’s policies.</p><h2>Accounts, credits, and payments</h2><p>AI features use a session cookie to track an anonymous account and credits. If an adult supplies an email for payment, account restoration, or card delivery, we store that email and relevant consent timestamps. Stripe processes purchases; we do not receive full payment-card details. Optional emails are sent through Cloudflare Email Service. The free manual studio does not require an email.</p><h2>Sharing and technical services</h2><p>Cards are not automatically published to a public gallery. Sending a downloaded file shares its included artwork and visible card details with the recipient. Avoid sensitive information on cards you share. Hosting providers may process ordinary access logs, such as IP addresses and request times. The studio does not add advertising trackers or analytics cookies.</p><h2>Aggregate usage counts</h2><p>To understand which pages and tools are useful, we keep daily totals such as visits, the page someone arrived on, the kind of site that referred them (for example a search engine), and how often features like download or print are used. Counting a daily visitor uses a one-way hash of the connection address and browser type with a random salt; the hashes and salt are deleted after two days, and only the totals are kept. These counts never include photos, card text, names, prompts, or email addresses.</p><h2>Children and adults creating together</h2><p>We encourage adults to supervise children’s creative use. Children should use a nickname and avoid submitting contact details. Purchases, optional account email, and AI photo processing are intended to be handled by an adult.</p><h2>Questions and deletion requests</h2><p>For server-side account questions, contact <a href="mailto:eric.wei@kevv.ai">eric.wei@kevv.ai</a> from your account email so we can identify the account. Local collection data can be removed directly from My collection or the browser’s site-data settings.</p>` : `<h2>A creative tool for personal play</h2><p>DIY Poké Card is an independent, fan-made trading-card editor. It is not affiliated with Nintendo, Game Freak, Creatures Inc., or The Pokémon Company. Pokémon and related marks belong to their respective owners. Cards made here are not official trading cards and are not intended for official tournament play or misrepresentation as authentic products.</p><h2>Your artwork and photos</h2><p>Use images you own or have permission to use. Do not upload private images of someone else without permission. An adult must approve AI photo processing, including permission from a parent or guardian for images of children. You retain any rights you already have in your uploaded material. AI output may be imperfect, may resemble other material, and is not guaranteed to be exclusive or suitable for commercial use.</p><h2>Free editing and optional AI credits</h2><p>The manual editor, supplied original companions, local collection, PNG export, interactive export, and home printing are free. AI generation is optional and uses credits. When available, anonymous accounts start with one promotional credit. Paid packs are shown before checkout: 15 artworks for $4.99, 40 for $9.99, or 90 for $19.99 USD, as one-time purchases without auto-renewal. Payment processing and any applicable checkout amounts are displayed by Stripe.</p><p>Paid credits are associated with the adult account email and can be restored through an emailed sign-in link when email service is available. Failed AI generation requests are designed to return the reserved credit automatically. If a purchase or credit fails, retain the receipt and contact eric.wei@kevv.ai for help.</p><h2>Saving and downloads</h2><p>Local drafts and collections belong to a browser profile. We cannot restore them after you erase site data unless you kept a backup. Download editable collection backups for cards you want to keep. Interactive HTML files should be opened only when you trust their source. PNG and printed files are static; physical foil and commercial printing are not included.</p><h2>Availability and reasonable use</h2><p>The service may change or be unavailable. AI features depend on configured external services. Do not abuse generation endpoints, bypass payment or account controls, upload harmful or unlawful material, or attempt to access other users’ data. We may restrict abusive use. No ranking, search traffic, creative result, or uninterrupted availability is guaranteed.</p>`;
  return shell({title:`${title} | DIY Poké Card`,description:privacy?'How the card editor handles local photos, saved collections, optional AI processing, and account data.':'Terms for using the free card editor, optional AI generation, downloads, and fan-made cards.',path:`/${kind}.html`,origin,body:`<div class="wrap"><header class="page-hero"><p class="breadcrumb"><a href="/">Home</a> / ${title}</p><h1>${title}</h1><p>Updated October 7, 2026.</p></header><article class="article-body" style="max-width:800px;padding-bottom:70px">${content}<p><a href="/studio">Back to creating →</a></p></article></div>`});
}
function notFound({origin=ORIGIN}={}) {return shell({title:'Card not found | DIY Poké Card',description:'This page wandered off. Start a new creation in the free card studio.',path:'/404',origin,noindex:true,body:`<section class="not-found"><span>404 ✧</span><h1>This little legend wandered off.</h1><p>The page is missing, but your next idea is waiting.</p><a class="btn" href="/studio">Back to the creation station ${icon('arrow')}</a></section>`});}
